SRC=['etatte kathitaṁ bhūpa devīmāhātmyamuttamam || 2||',
'evaṁ prabhāvā sā devī yayedaṁ dhāryate jagat| / vidyā tathaiva kriyate bhagavadviṣṇumāyayā || 3||',
'tayā tvayeṣa vaiśyaśca tathaivānye vivekinaḥ | / mohyante mohitāścaiva mohameṣyanti cāpare || 4||',
'tāmupaihi mahārāja śaraṇaṁ parameśvarīm | / ārādhitā saiva nṛṇāṁ bhogasvargāpavargadā || 5||',
'iti tasya vacaḥ śrutvā surathaḥ sa narādhipaḥ | / praṇipatya mahābhāgaṁ tamṛṣiṁ saṁśitavratam || 7|| / nirviṇṇo’timamatvena rājyāpaharaṇena ca| / jagāma sadyastapase sa ca vaiśyo mahāmune || 8||',
'sandarśanārthamambāyā nadīpulinamāsthitaḥ | / sa ca vaiśyastapastepe devīsūktaṁ paraṁ japan || 9||',
'tau tasmin puline devyāḥ kṛtvā mūrtiṁ mahīmayīm | / arhaṇāṁ cakratustasyāḥ puṣpadhūpāgnitarpaṇaiḥ || 10||',
'nirāhārau yatātmānau tanmanaskau samāhitau | / dadatustau baliṁ caiva nijagātrāsṛgukṣitam || 11||',
'evaṁ samārādhayatostribhirvarṣairyatātmanoḥ | / parituṣṭā jagaddhātrī pratyakṣaṁ prāha caṇḍikā || 12||',
'yatprārthyate tvayā bhūpa tvayā ca kulanandana | / mattastatprāpyatāṁ sarvaṁ parituṣṭā dadāmi te || 14||',
'tato vavre nṛpo rājyamavibhraṁśyanyajanmani | / atraiva ca nijaṁ rājyaṁ hataśatrubalaṁ balāt || 16||',
'so’pi vaiśyastato jñānaṁ vavre nirviṇṇamānasaḥ | / mametyahamiti prājñaḥ saṅgavicyutikārakam || 17||',
'svalpairahobhirnṛpate svaṁ rājyaṁ prāpsyate bhavān || 19|| / hatvā ripūnaskhalitaṁ tava tatra bhaviṣyati || 20||',
'mṛtaśca bhūyaḥ samprāpya janma devādvivasvataḥ || 21|| / sāvarṇiko manurnāma bhavānbhuvi bhaviṣyati || 22||',
'vaiśyavarya tvayā yaśca varo’smatto’bhivāñchitaḥ || 23|| / taṁ prayacchāmi saṁsiddhyai tava jñānaṁ bhaviṣyati || 24||',
'iti dattvā tayordevī yathābhilaṣitaṁ varam | / babhūvāntarhitā sadyo bhaktyā tābhyāmabhiṣṭutā || 26–27||',
'evaṁ devyā varaṁ labdhvā surathaḥ kṣatriyarṣabhaḥ | / sūryājjanma samāsādya sāvarṇirbhavitā manuḥ || 28–29||']
def num(s): return re.findall(r'\|\|\s*([\d–]+)\s*\|\|',s)
FV=[dict(n=('–'.join([num(s)[0].split('–')[0],num(s)[-1].split('–')[-1]]) if (len(num(s))>1 or '–' in num(s)[0]) else num(s)[0]),lines=L(s)) for s in SRC]
for f in FV:
    if f['n']=='2': f['lines']=[[L(SRC[0])[0][0],'']]
def S(*ns): return ' / '.join(s for s in SRC if any(x in num(s) for x in ns))
def KS(x,y,s=1): return KING(x,y,s)
RIVER='<rect width="220" height="160" fill="#e7f4ea"/><path d="M0 120 q55 -12 110 0 t110 0 V160 H0z" fill="#4aa3df" stroke="#111"/><path d="M0 116 q55 -12 110 0 t110 0" fill="none" stroke="#e8d8a8" stroke-width="8"/>'
